expected=dict(irq_r11=77,irq_unit_r11=18,return_guard_r11=17,no_diag_r11=4,timing_platform=3,timing_legacy=4,cdc_r11_5=9,exsp_work_r11_2=12,msx_request_r11_3=2,slot_r11_4=0,write_r17=4,sd_r11_9=8,upper_r17=6,mbase_r12=9,madl_r13=78,mixed_r14=192,mix_nodiag_r14=1,tst_r15=12,tst_com_nodiag_r15=1,tst_z80_r15=3,diag_r15_1=7,diag_r15_2=8,ldh_unit_r16=6,ldx_unit_r17=6,ldx_com_nodiag_r17=1,ldx_adl_irq_r17=6)
